package org.nationalrevivaldesk.app;
import android.content.Context;import androidx.annotation.NonNull;import androidx.work.*;import org.json.JSONObject;import java.util.List;import java.util.concurrent.TimeUnit;
public class SyncWorker extends Worker { public SyncWorker(@NonNull Context context,@NonNull WorkerParameters params){super(context,params);} @NonNull @Override public Result doWork(){try{ApiClient api=new ApiClient(getApplicationContext());if(api.token().isEmpty())return Result.success();List<OfflineAction> items=AppDatabase.get(getApplicationContext()).queue().pending();for(OfflineAction item:items){try{api.post(item.endpoint,new JSONObject(item.payloadJson));AppDatabase.get(getApplicationContext()).queue().delete(item.id);}catch(Exception error){AppDatabase.get(getApplicationContext()).queue().update(item.id,"failed");}}return Result.success();}catch(Exception error){return Result.retry();}} public static void schedule(Context context){Constraints constraints=new Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build();PeriodicWorkRequest work=new PeriodicWorkRequest.Builder(SyncWorker.class,15,TimeUnit.MINUTES).setConstraints(constraints).build();WorkManager.getInstance(context).enqueueUniquePeriodicWork("nrd-sync",ExistingPeriodicWorkPolicy.KEEP,work);} }
